<?php require_once __DIR__.'/_common.php';$riwayat=get_riwayat($pdo,$idLansia);awal_halaman('Riwayat Kesehatan','riwayat'); ?>
<section class="f-intro"><h1>Riwayat Kesehatan Lansia</h1><p>Catatan pemeriksaan yang sudah dimasukkan oleh kader Posyandu untuk lansia yang terdaftar pada akun keluarga Anda.</p></section>
<section class="f-card"><h3>Daftar Riwayat Pemeriksaan</h3><?php if($riwayat):?><div class="f-table-wrap"><table class="f-table"><thead><tr><th>Tanggal & waktu</th><th>Nama lansia</th><th>Berat / tinggi</th><th>IMT</th><th>Tekanan darah</th><th>Nadi</th><th>Suhu</th><th>Status</th></tr></thead><tbody><?php foreach($riwayat as $r):?><tr><td><?=tgl_id($r['tanggal_pemeriksaan'])?><br><?=jam_id($r['waktu_pemeriksaan'])?></td><td><b><?=h($r['nama_lansia'])?></b></td><td><?=h($r['berat_badan'])?> kg / <?=h($r['tinggi_badan'])?> cm</td><td><?=h($r['imt'])?><br><?=h($r['status_imt'])?></td><td><?=(int)$r['tensi_sistolik']?>/<?=(int)$r['tensi_diastolik']?> mmHg<br><?=h($r['status_tensi'])?></td><td><?=(int)$r['detak_jantung']?> bpm</td><td><?=h($r['suhu_tubuh'])?> °C</td><td><span class="f-badge <?=warna_status($r['status_kondisi'])?>"><?=h($r['status_kondisi'])?></span></td></tr><tr><td colspan="8" style="background:#fafcfd"><b>Gula darah:</b> <?=$r['gula_darah']===null?'Tidak diperiksa':h($r['gula_darah']).' mg/dL ('.h($r['status_gula_darah']).')'?> &nbsp; <b>Kolesterol:</b> <?=$r['kolesterol']===null?'Tidak diperiksa':h($r['kolesterol']).' mg/dL ('.h($r['status_kolesterol']).')'?> &nbsp; <b>Asam urat:</b> <?=$r['asam_urat']===null?'Tidak diperiksa':h($r['asam_urat']).' mg/dL ('.h($r['status_asam_urat']).')'?><br><b>Keluhan:</b> <?=h($r['keluhan']?:'Tidak ada catatan')?><br><b>Catatan kader:</b> <?=h($r['catatan_kader']?:'Tidak ada catatan')?><br><b>Rujukan Puskesmas:</b> <?=h($r['rujukan_puskesmas'])?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="f-empty">Belum ada riwayat pemeriksaan untuk lansia yang terhubung dengan akun Anda.</div><?php endif;?></section>
